from pathlib import Path
from html_fidelity_assets import png
from html_fidelity_layers import encode_png

def main():
 a=argparse.ArgumentParser();a.add_argument('--prototype',type=Path,required=True);a.add_argument('--layers',type=Path,required=True);a=a.parse_args();out=a.layers;report=json.loads((out/'layer_measurements.json').read_text(encoding='utf8'));source=(a.prototype/'anlogic-exhibit.html').read_text(encoding='utf8');seed='<script>let seed=20261015;Math.random=()=>((seed=(1664525*seed+1013904223)>>>0)/4294967296);window.requestAnimationFrame=()=>0;</script>';source=source.replace('<script>',seed+'<script>',1)
 css='''<style>html,body{width:640px;height:480px;display:block!important;overflow:hidden!important;background:transparent!important}.viewport{position:absolute!important;left:0;top:0;width:640px;height:480px;padding:0!important;display:block!important;min-height:0!important}.frame{position:absolute!important;left:0;top:0;width:640px!important;height:480px!important;box-shadow:none!important}#stage{transform:none!important}.panel,.viewport-meta,#osd,#bot{display:none!important}*,*::before,*::after{animation:none!important;transition:none!important}</style>'''
 for idx,page in enumerate(report['pages']):
  f=out/'native_bg.html';sc=f'''S.playing=false;scenes.forEach(s=>s.className='scene '+PAGES[scenes.indexOf(s)].cls);let sc=scenes[{idx}];sc.classList.add('on');let bg=sc.querySelector('.bg');sc.querySelectorAll('*').forEach(e=>{{if(e!==bg&&!bg.contains(e))e.style.visibility='hidden';}});''';f.write_text(source.replace('</head>',css+'</head>').replace('</body>','<script>'+sc+'</script></body>'),encoding='utf8');bg=page['layers'][0];target=out/(bg['name']+'_native.png');cmd=['/Applications/Google Chrome.app/Contents/MacOS/Google Chrome','--headless','--disable-gpu','--no-first-run','--hide-scrollbars','--force-device-scale-factor=1','--default-background-color=00000000',f'--user-data-dir={out/"chrome_profile"}','--window-size=640,480','--virtual-time-budget=300',f'--screenshot={target}',f.as_uri()];t=time.monotonic();p=subprocess.Popen(cmd,stdout=subprocess.PIPE,stderr=subprocess.PIPE);stdout,stderr=p.communicate(timeout=40);assert p.returncode==0;(out/(bg['name']+'_native.log')).write_bytes(stdout+stderr)
  w,h,r=png(target);assert(w,h)==(640,480) and set(r[3::4])=={255};padded=bytearray(896*736*4)
  for y in range(480):padded[((y+128)*896+128)*4:((y+128)*896+768)*4]=r[y*640*4:(y+1)*640*4]
  original=out/(bg['name']+'.png');original.rename(out/(bg['name']+'_gutter_original.png'));bg['gutter_original_sha256']=bg['sha256'];bg['native_origin_source_sha256']=hashlib.sha256(target.read_bytes()).hexdigest();bg['native_renderer_pid']=p.pid;bg['native_renderer_exit']=p.returncode;bg['native_renderer_wall_seconds']=time.monotonic()-t;encode_png(original,896,736,padded);(out/(bg['name']+'_crop.png')).write_bytes(target.read_bytes());bg['sha256']=hashlib.sha256(original.read_bytes()).hexdigest();colors={tuple(r[i:i+3])for i in range(0,len(r),4)};bg['rgb_colors']=len(colors);bg['lossless_rgb_index_bits']=math.ceil(math.log2(len(colors)));bg['lossless_index_bytes']=math.ceil(307200*bg['lossless_rgb_index_bits']/8)+len(colors)*3
 report['notes'].append('BG recaptured atoriginal native640x480 origin, then padded onlyafterrasterization;128pxgutter rendering changedproceduralSVGnoise phase. InitialgutterBG retained.');(out/'layer_measurements.json').write_text(json.dumps(report,indent=2),encoding='utf8');print('NATIVE_BG_PHASE_CORRECTION_COMPLETE')
